import React, { useState } from 'react';
import { saveConsultationLocal } from '../utils/localStorageApi';

/**
 * 상담 저장하기 버튼과 고객 정보 입력 폼
 * 서버 호출 제거 → 로컬스토리지에만 저장
 */
export default function SaveConsultationButton({ formData }) {
  // 고객 정보
  const [customerType, setCustomerType] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // UI 상태
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);

  // 폼 열기
  const handleStart = () => {
    setShowForm(true);
    setError(null);
    setSuccess(false);
  };

  // 저장 처리 (로컬스토리지만)
  const handleSubmit = () => {
    if (!customerType || !customerName || !customerPhone) {
      setError('구분, 이름, 전화번호를 모두 입력해주세요.');
      return;
    }
    setLoading(true);
    setError(null);

    const payload = {
      ...formData,
      customerType,
      customerName,
      customerPhone,
      savedAt: Date.now(),
    };

    try {
      saveConsultationLocal(payload);
      setSuccess(true);
      setShowForm(false);
    } catch (err) {
      console.error('로컬 저장 오류:', err);
      setError('로컬 저장 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-4 p-4 border rounded-2xl shadow-sm bg-white max-w-md">
      {!showForm ? (
        <button
          onClick={handleStart}
          className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl"
        >
          상담 저장하기
        </button>
      ) : (
        <div className="flex flex-col space-y-3">
          {/* 고객 구분 */}
          <div>
            <label className="block text-sm font-medium">구분</label>
            <select
              value={customerType}
              onChange={e => setCustomerType(e.target.value)}
              className="mt-1 block w-full border-gray-300 rounded p-2"
            >
              <option value="">선택하세요</option>
              <option value="타사">타사</option>
              <option value="신규">신규</option>
              <option value="기변">기변</option>
            </select>
          </div>

          {/* 이름 */}
          <div>
            <label className="block text-sm font-medium">이름</label>
            <input
              type="text"
              value={customerName}
              onChange={e => setCustomerName(e.target.value)}
              className="mt-1 block w-full border-gray-300 rounded p-2"
              placeholder="홍길동"
            />
          </div>

          {/* 전화번호 */}
          <div>
            <label className="block text-sm font-medium">전화번호</label>
            <input
              type="tel"
              value={customerPhone}
              onChange={e => setCustomerPhone(e.target.value)}
              className="mt-1 block w-full border-gray-300 rounded p-2"
              placeholder="010-1234-5678"
            />
          </div>

          {/* 에러 메시지 */}
          {error && <p className="text-red-600 text-sm">{error}</p>}

          {/* 버튼 그룹 */}
          <div className="flex space-x-2">
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="flex-1 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-2xl"
            >
              {loading ? '저장 중…' : '확인'}
            </button>
            <button
              onClick={() => setShowForm(false)}
              disabled={loading}
              className="flex-1 px-4 py-2 bg-gray-300 hover:bg-gray-400 text-gray-800 rounded-2xl"
            >
              취소
            </button>
          </div>
        </div>
      )}
      {success && <p className="mt-2 text-green-600">상담이 로컬에 저장되었습니다!</p>}
    </div>
  );
}
