import React from 'react';
import { useScreenshot } from '../utils/useScreenshot';

export default function ShareButton({ className = '' }) {
  const { isCapturing, captureAndShare } = useScreenshot('body', {
    logging: false,
    backgroundColor: null,
  });

  return (
    <button
      onClick={captureAndShare}
      disabled={isCapturing}
      className={`${className} w-full py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 disabled:opacity-50`}
    >
      {isCapturing ? '캡처 중…' : '공유하기'}
    </button>
  );
}
